1	// Forward harness (DESIGN.md §"Forward run", §"Stop rule"): each pre-registered backlog task runs through the old and
2	// the new setup in paired worktrees from one commit, both results are graded, the winner is merged, and the pair is recorded.
3	import { Database } from "bun:sqlite";
4	import { existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
5	import { tmpdir } from "node:os";
6	import { dirname, join, relative, resolve } from "node:path";
7	import { grade, isTestFile } from "../grade/index.ts";
8	import type { HiddenTest } from "../grade/index.ts";
9	import type { LlmClient } from "../llm/types.ts";
10	import { createSandbox, destroySandbox, runGit } from "../sandbox/index.ts";
11	import type { ForwardPair } from "../types.ts";
12	import { assignLabels, blindJudge, chooseMerge, pairSeed, rng } from "./blind.ts";
13	import type { MergeChoice, Side } from "./blind.ts";
14	
15	export * from "./blind.ts";
16	
17	export const DEFAULT_FORWARD_DB = ".roster/roster.db";
18	export const MIN_PAIRS = 15;
19	export const MIN_NET_LOSSES = 3;
20	
21	export interface BacklogTask {
22	  id: string;
23	  /** The task text, without the setup tag line. */
24	  body: string;
25	  /** Paths from the task's OWNS line; the scope guard allows edits only there. Empty when the task names none. */
26	  owns: string[];
27	}
28	
29	/** Task blocks sit between "<!-- Txx -->" and "<!-- /Txx -->", the format scripts/run-setup.sh reads. */
30	export function parseBacklog(text: string): BacklogTask[] {
31	  const tasks: BacklogTask[] = [];
32	  const re = /^<!-- (\S+) -->\n([\s\S]*?)^<!-- \/\1 -->/gm;
33	  for (const m of text.matchAll(re)) {
34	    const lines = m[2]!.replace(/\n+$/, "").split("\n");
35	    if (lines[0]?.startsWith("[roster ")) lines.shift();
36	    const body = lines.join("\n");
37	    const owns = /^OWNS:\s*(.+)$/m.exec(body)?.[1]?.split(/[,\s]+/).map((s) => s.replace(/[`.;]+$/g, "").replace(/^`/, "")).filter((s) => s.includes("/") || s.includes(".")) ?? [];
38	    tasks.push({ id: m[1]!, body, owns });
39	  }
40	  return tasks;
41	}
42	
43	export const setupTag = (setup: string, task: string) => `[roster setup=${setup} task=${task}]`;
44	
45	/** A backlog containing only `task`, tagged for `setup`, in the format scripts/run-setup.sh expects. */
46	export function taggedBlock(task: BacklogTask, setup: string): string {
47	  return `<!-- ${task.id} -->\n${setupTag(setup, task.id)}\n${task.body}\n<!-- /${task.id} -->\n`;
48	}
49	
50	// ---- state ----
51	
52	export class ForwardStore {
53	  readonly db: Database;
54	  constructor(path: string) {
55	    if (path !== ":memory:") mkdirSync(dirname(resolve(path)), { recursive: true });
56	    this.db = new Database(path, { create: true });
57	    this.db.exec(`CREATE TABLE IF NOT EXISTS forward_pairs (
58	      task_id TEXT PRIMARY KEY, setup_old TEXT NOT NULL, setup_new TEXT NOT NULL, pass_old INTEGER NOT NULL, pass_new INTEGER NOT NULL,
59	      cost_old REAL, cost_new REAL, merged TEXT, blind_labels TEXT NOT NULL, seed INTEGER NOT NULL, seq INTEGER NOT NULL)`);
60	    this.db.exec("CREATE TABLE IF NOT EXISTS forward_state (key TEXT PRIMARY KEY, value TEXT NOT NULL)");
61	  }
62	
63	  pairs(): ForwardPair[] {
64	    const rows = this.db.query("SELECT * FROM forward_pairs ORDER BY seq").all() as Record<string, unknown>[];
65	    return rows.map((r) => ({
66	      task_id: r.task_id as string,
67	      setup_old: r.setup_old as string,
68	      setup_new: r.setup_new as string,
69	      pass_old: r.pass_old === 1,
70	      pass_new: r.pass_new === 1,
71	      cost_old: r.cost_old as number | null,
72	      cost_new: r.cost_new as number | null,
73	      merged: r.merged as "old" | "new" | null,
74	      blind_labels: JSON.parse(r.blind_labels as string),
75	      seed: r.seed as number,
76	    }));
77	  }
78	
79	  addPair(p: ForwardPair): void {
80	    const seq = (this.db.query("SELECT COUNT(*) AS n FROM forward_pairs").get() as { n: number }).n;
81	    this.db
82	      .query("INSERT OR REPLACE INTO forward_pairs VALUES (?,?,?,?,?,?,?,?,?,?,?)")
83	      .run(p.task_id, p.setup_old, p.setup_new, +p.pass_old, +p.pass_new, p.cost_old, p.cost_new, p.merged, JSON.stringify(p.blind_labels), p.seed, seq);
84	  }
85	
86	  getState(key: string): string | null {
87	    return (this.db.query("SELECT value FROM forward_state WHERE key = ?").get(key) as { value: string } | null)?.value ?? null;
88	  }
89	  setState(key: string, value: string): void {
90	    this.db.query("INSERT OR REPLACE INTO forward_state VALUES (?, ?)").run(key, value);
91	  }
92	  close(): void {
93	    this.db.close();
94	  }
95	}
96	
97	// ---- stop rule ----
98	
99	export interface StopRuleState {
100	  pairs: number;
101	  /** Discordant pairs NEW won (NEW passed, OLD failed) and lost. */
102	  won: number;
103	  lost: number;
104	  triggered: boolean;
105	}
106	
107	export function evaluateStopRule(pairs: ForwardPair[]): StopRuleState {
108	  const won = pairs.filter((p) => p.pass_new && !p.pass_old).length;
109	  const lost = pairs.filter((p) => !p.pass_new && p.pass_old).length;
110	  return { pairs: pairs.length, won, lost, triggered: pairs.length >= MIN_PAIRS && lost - won >= MIN_NET_LOSSES };
111	}
112	
113	export interface RevertRequest {
114	  setupOld: string;
115	  setupNew: string;
116	  state: StopRuleState;
117	}
118	export interface RevertOutcome {
119	  url: string | null;
120	  stub: boolean;
121	}
122	
123	/** Opens the revert PR through src/act when it exists; until then it is a logged stub. */
124	export async function defaultOpenRevertPr(req: RevertRequest): Promise<RevertOutcome> {
125	  const spec = "../act/index.ts";
126	  if (existsSync(join(import.meta.dir, spec))) {
127	    const mod = (await import(spec)) as { openRevertPr?: (r: RevertRequest) => Promise<{ url?: string | null }> };
128	    if (mod.openRevertPr) return { url: (await mod.openRevertPr(req)).url ?? null, stub: false };
129	  }
130	  return { url: null, stub: true };
131	}
132	
133	// ---- harness ----
134	
135	export interface HarnessRequest {
136	  task: BacklogTask;
137	  setup: string;
138	  side: Side;
139	  /** A worktree on its own branch at the pair's base commit, already created. */
140	  worktree: string;
141	  branch: string;
142	  /** A task file holding this task's block tagged for this setup (ROSTER_TASKS). */
143	  tasksFile: string;
144	}
145	export interface HarnessResult {
146	  costUsd: number | null;
147	}
148	export type Harness = (req: HarnessRequest) => Promise<HarnessResult>;
149	
150	/** Launches scripts/run-setup.sh, which pre-existing worktrees skip creating, so both sides share one base commit. */
151	export function runSetupHarness(repo: string): Harness {
152	  return async (req) => {
153	    const env = {
154	      ...process.env,
155	      ROSTER_TASKS: req.tasksFile,
156	      ROSTER_WT: dirname(req.worktree),
157	    };
158	    const proc = Bun.spawn(["bash", join(repo, "scripts", "run-setup.sh"), req.setup, req.task.id], { cwd: repo, env, stdout: "pipe", stderr: "pipe" });
159	    await proc.exited;
160	    const log = join(repo, ".roster", "runs", `${req.task.id}.${req.setup}.jsonl`);
161	    let costUsd: number | null = null;
162	    try {
163	      const line = readFileSync(log, "utf8").split("\n").filter((l) => l.includes('"type":"result"')).at(-1);
164	      const c = line ? JSON.parse(line).total_cost_usd : null;
165	      costUsd = typeof c === "number" ? c : null;
166	    } catch {
167	      /* no log: cost stays unknown, never a guess */
168	    }
169	    return { costUsd };
170	  };
171	}
172	
173	// ---- helpers ----
174	
175	class Mutex {
176	  private tail: Promise<void> = Promise.resolve();
177	  run<T>(fn: () => Promise<T> | T): Promise<T> {
178	    const r = this.tail.then(fn);
179	    this.tail = r.then(
180	      () => undefined,
181	      () => undefined,
182	    );
183	    return r;
184	  }
185	}
186	
187	function walk(dir: string): string[] {
188	  return readdirSync(dir).flatMap((n) => {
189	    const p = join(dir, n);
190	    return statSync(p).isDirectory() ? walk(p) : [p];
191	  });
192	}
193	
194	/** Acceptance tests for a task: every file under <acceptanceDir>/<id>/, mirrored at the same relative path in the repo. */
195	export function loadAcceptance(acceptanceDir: string, id: string): HiddenTest[] {
196	  const dir = join(acceptanceDir, id);
197	  if (!existsSync(dir)) return [];
198	  return walk(dir).map((f) => ({ path: relative(dir, f), content: readFileSync(f, "utf8") }));
199	}
200	
201	export interface SideGrade {
202	  pass: boolean;
203	  hiddenPass: boolean;
204	  suitePass: boolean;
205	  scopeOk: boolean;
206	}
207	
208	async function gradeBranch(opts: {
209	  repo: string;
210	  base: string;
211	  head: string;
212	  hidden: HiddenTest[];
213	  owns: string[];
214	  testCmd?: string;
215	  scratch: string;
216	}): Promise<SideGrade> {
217	  const sandbox = await createSandbox(opts.repo, opts.base, { root: opts.scratch });
218	  try {
219	    const patch = runGit(opts.repo, ["diff", "--binary", opts.base, opts.head]);
220	    if (patch) {
221	      const pf = join(sandbox.path, "..", `${sandbox.path.split("/").at(-1)}.patch`);
222	      writeFileSync(pf, patch + "\n");
223	      runGit(sandbox.path, ["apply", "--binary", pf]);
224	      rmSync(pf, { force: true });
225	    }
226	    const preexistingTests = runGit(opts.repo, ["ls-tree", "-r", "--name-only", opts.base]).split("\n").filter((p) => p && isTestFile(p));
227	    const r = await grade({
228	      sandbox,
229	      hidden: opts.hidden,
230	      preexistingTests,
231	      touchedDirs: opts.owns.length ? opts.owns : undefined,
232	      testCmd: opts.testCmd,
233	    });
234	    return { pass: r.hiddenPass && r.suitePass && r.scopeOk, hiddenPass: r.hiddenPass, suitePass: r.suitePass, scopeOk: r.scopeOk };
235	  } finally {
236	    await destroySandbox(sandbox.path);
237	  }
238	}
239	
240	// ---- the run ----
241	
242	export interface ForwardOptions {
243	  repo: string;
244	  backlog: string;
245	  pair: { old: string; new: string };
246	  parallel?: number;
247	  harness?: Harness;
248	  /** The blind diff-judge's model client. */
249	  llm: LlmClient;
250	  db?: string;
251	  wtRoot?: string;
252	  acceptanceDir?: string;
253	  /** Overrides test-command detection for the full suite and the acceptance tests. */
254	  testCmd?: string;
255	  /** Run seed; each pair's seed is derived from it and the task id. Default: random, and logged. */
256	  seed?: number;
257	  openRevertPr?: (req: RevertRequest) => Promise<RevertOutcome>;
258	  log?: (line: string) => void;
259	}
260	
261	export interface ForwardSummary {
262	  completed: ForwardPair[];
263	  skipped: string[];
264	  /** Tasks run on the old setup alone after the stop rule triggered. */
265	  soloOnOld: string[];
266	  stop: StopRuleState;
267	  reverted: RevertOutcome | null;
268	  seed: number;
269	}
270	
271	export async function runForward(opts: ForwardOptions): Promise<ForwardSummary> {
272	  const log = opts.log ?? (() => undefined);
273	  const repo = resolve(opts.repo);
274	  const wtRoot = resolve(opts.wtRoot ?? "/Users/Shared/roster-wt/forward");
275	  const acceptanceDir = resolve(repo, opts.acceptanceDir ?? "experiments/acceptance");
276	  const harness = opts.harness ?? runSetupHarness(repo);
277	  const store = new ForwardStore(resolve(opts.db ?? DEFAULT_FORWARD_DB));
278	  const tasks = parseBacklog(opts.backlog);
279	  const runSeed = opts.seed ?? Number(store.getState("seed") ?? Math.floor(Math.random() * 2 ** 31));
280	  store.setState("seed", String(runSeed));
281	  log(`forward: run seed ${runSeed}`);
282	
283	  const done = new Set(store.pairs().map((p) => p.task_id));
284	  const solo = new Set<string>(JSON.parse(store.getState("solo") ?? "[]"));
285	  const skipped = tasks.filter((t) => done.has(t.id) || solo.has(t.id)).map((t) => t.id);
286	  const queue = tasks.filter((t) => !done.has(t.id) && !solo.has(t.id));
287	  const git = new Mutex();
288	  const scratch = mkdtempSync(join(tmpdir(), "roster-forward-"));
289	  const completed: ForwardPair[] = [];
290	  const soloOnOld: string[] = [];
291	  let reverted: RevertOutcome | null = store.getState("reverted") ? JSON.parse(store.getState("reverted")!) : null;
292	  let revertedFlag = reverted !== null;
293	
294	  const startSide = async (task: BacklogTask, side: Side, setup: string, base: string) => {
295	    const worktree = join(wtRoot, side, task.id);
296	    const branch = `forward/${task.id}/${side}`;
297	    await git.run(() => {
298	      if (!existsSync(worktree)) {
299	        mkdirSync(dirname(worktree), { recursive: true });
300	        const exists = Bun.spawnSync(["git", "rev-parse", "--verify", "-q", branch], { cwd: repo }).exitCode === 0;
301	        runGit(repo, exists ? ["worktree", "add", "-q", worktree, branch] : ["worktree", "add", "-q", worktree, "-b", branch, base]);
302	      }
303	    });
304	    const tasksFile = join(scratch, `${task.id}.${side}.md`);
305	    writeFileSync(tasksFile, taggedBlock(task, setup));
306	    const res = await harness({ task, setup, side, worktree, branch, tasksFile });
307	    // Whatever the agent left uncommitted is part of its change.
308	    const head = await git.run(() => {
309	      runGit(worktree, ["add", "-A"]);
310	      if (runGit(worktree, ["status", "--porcelain"])) runGit(worktree, ["-c", "commit.gpgsign=false", "commit", "-q", "-m", `${task.id}: uncommitted work from ${side} run`]);
311	      return runGit(worktree, ["rev-parse", "HEAD"]);
312	    });
313	    return { branch, head, costUsd: res.costUsd };
314	  };
315	
316	  const mergeBranch = (task: BacklogTask, branch: string, setup: string) =>
317	    git.run(() => {
318	      const r = Bun.spawnSync(["git", "merge", "--no-ff", "-m", `${task.id}: merge forward winner (${setup})`, branch], { cwd: repo, env: { ...process.env, GIT_EDITOR: "true" } });
319	      if (r.exitCode !== 0) {
320	        Bun.spawnSync(["git", "merge", "--abort"], { cwd: repo });
321	        log(`forward: ${task.id}: merge of ${branch} failed, left unmerged: ${r.stderr.toString().trim()}`);
322	        return false;
323	      }
324	      return true;
325	    });
326	
327	  const runPair = async (task: BacklogTask): Promise<ForwardPair> => {
328	    const base = await git.run(() => runGit(repo, ["rev-parse", "HEAD"]));
329	    const seed = pairSeed(runSeed, task.id);
330	    const random = rng(seed);
331	    const [o, n] = await Promise.all([startSide(task, "old", opts.pair.old, base), startSide(task, "new", opts.pair.new, base)]);
332	    const hidden = loadAcceptance(acceptanceDir, task.id);
333	    const gradeSide = (s: { head: string }) => gradeBranch({ repo, base, head: s.head, hidden, owns: task.owns, testCmd: opts.testCmd, scratch });
334	    const [go, gn] = await Promise.all([gradeSide(o), gradeSide(n)]);
335	    const pass = { old: go.pass, new: gn.pass };
336	
337	    let labels = assignLabels(random);
338	    let preferred: Side | null = null;
339	    if (pass.old && pass.new) {
340	      const diffs = {
341	        old: runGit(repo, ["diff", base, o.head]),
342	        new: runGit(repo, ["diff", base, n.head]),
343	      };
344	      // A fresh stream from the same seed draws the same labels as above, so the logged seed reproduces them.
345	      const judged = await blindJudge(opts.llm, task.body, diffs, rng(seed), [opts.pair.old, opts.pair.new]);
346	      labels = judged.labels;
347	      preferred = judged.preferred;
348	      log(`forward: ${task.id}: judge ${judged.verdict} (X=${labels.X}, Y=${labels.Y})`);
349	    }
350	    const choice: MergeChoice = chooseMerge(pass, preferred, random);
351	    let merged = choice.merged;
352	    if (merged) {
353	      const w = merged === "old" ? o : n;
354	      if (!(await mergeBranch(task, w.branch, opts.pair[merged]))) merged = null;
355	    }
356	    log(`forward: ${task.id}: old ${pass.old ? "pass" : "fail"}, new ${pass.new ? "pass" : "fail"}, ${choice.reason}, merged ${merged ?? "none"}, seed ${seed}`);
357	    const pair: ForwardPair = {
358	      task_id: task.id,
359	      setup_old: opts.pair.old,
360	      setup_new: opts.pair.new,
361	      pass_old: pass.old,
362	      pass_new: pass.new,
363	      cost_old: o.costUsd,
364	      cost_new: n.costUsd,
365	      merged,
366	      blind_labels: labels,
367	      seed,
368	    };
369	    return pair;
370	  };
371	
372	  const runSolo = async (task: BacklogTask) => {
373	    const base = await git.run(() => runGit(repo, ["rev-parse", "HEAD"]));
374	    const o = await startSide(task, "old", opts.pair.old, base);
375	    const g = await gradeBranch({ repo, base, head: o.head, hidden: loadAcceptance(acceptanceDir, task.id), owns: task.owns, testCmd: opts.testCmd, scratch });
376	    if (g.pass) await mergeBranch(task, o.branch, opts.pair.old);
377	    solo.add(task.id);
378	    soloOnOld.push(task.id);
379	    store.setState("solo", JSON.stringify([...solo]));
380	    log(`forward: ${task.id}: run on old setup only (stop rule): ${g.pass ? "pass, merged" : "fail"}`);
381	  };
382	
383	  const onPair = async (pair: ForwardPair) => {
384	    store.addPair(pair);
385	    completed.push(pair);
386	    const state = evaluateStopRule(store.pairs());
387	    if (state.triggered && !revertedFlag) {
388	      revertedFlag = true;
389	      log(`forward: stop rule: new lost ${state.lost}, won ${state.won} discordant pairs over ${state.pairs}; opening revert PR`);
390	      reverted = await (opts.openRevertPr ?? defaultOpenRevertPr)({ setupOld: opts.pair.old, setupNew: opts.pair.new, state });
391	      store.setState("reverted", JSON.stringify(reverted));
392	      log(reverted.stub ? "forward: revert PR is a stub (src/act is absent); continuing on the old setup" : `forward: revert PR ${reverted.url}; continuing on the old setup`);
393	    }
394	  };
395	
396	  const worker = async () => {
397	    for (let t = queue.shift(); t; t = queue.shift()) {
398	      if (revertedFlag) await runSolo(t);
399	      else await onPair(await runPair(t));
400	    }
401	  };
402	  try {
403	    await Promise.all(Array.from({ length: Math.max(1, opts.parallel ?? 4) }, worker));
404	  } finally {
405	    rmSync(scratch, { recursive: true, force: true });
406	  }
407	  const stop = evaluateStopRule(store.pairs());
408	  store.close();
409	  return { completed, skipped, soloOnOld, stop, reverted, seed: runSeed };
410	}
