1	// Blind grading for the forward run (DESIGN.md §"Forward run"): random X/Y labels, a judge that sees only the
2	// labelled diffs, and the merge policy. Randomness is a seeded PRNG so every pick can be replayed from the logged seed.
3	import type { ChatMessage, LlmClient } from "../llm/types.ts";
4	
5	export type Side = "old" | "new";
6	export type Verdict = "X" | "Y" | "tie";
7	
8	/** mulberry32: a small deterministic PRNG, so a logged seed reproduces labels and tie-breaks. */
9	export function rng(seed: number): () => number {
10	  let a = seed >>> 0;
11	  return () => {
12	    a = (a + 0x6d2b79f5) >>> 0;
13	    let t = a;
14	    t = Math.imul(t ^ (t >>> 15), t | 1);
15	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
16	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
17	  };
18	}
19	
20	/** A per-pair seed derived from the run seed and the task id (FNV-1a), stable across resumes. */
21	export function pairSeed(runSeed: number, taskId: string): number {
22	  let h = (0x811c9dc5 ^ runSeed) >>> 0;
23	  for (const ch of taskId) h = Math.imul(h ^ ch.charCodeAt(0), 0x01000193) >>> 0;
24	  return h;
25	}
26	
27	/** Which side is shown as X; the other is Y. */
28	export function assignLabels(random: () => number): Record<"X" | "Y", Side> {
29	  return random() < 0.5 ? { X: "old", Y: "new" } : { X: "new", Y: "old" };
30	}
31	
32	/** Removes anything that names a setup or the branch it ran on, so the judge cannot tell the sides apart. */
33	export function scrub(text: string, hide: string[]): string {
34	  let out = text.replace(/forward\/[\w.-]+\/(old|new)/g, "<branch>");
35	  for (const h of hide.filter((s) => s.length > 0)) out = out.split(h).join("<setup>");
36	  return out;
37	}
38	
39	const SYSTEM = `You compare two candidate changes, X and Y, for the same task. You know nothing about who or what wrote them.
40	Judge correctness against the task, then scope discipline, then simplicity. Reply with one line: "verdict: X", "verdict: Y" or "verdict: tie".`;
41	
42	/** The judge's whole input: the task text and the two labelled diffs, nothing that identifies a setup. */
43	export function blindMessages(task: string, diffX: string, diffY: string, hide: string[] = []): ChatMessage[] {
44	  const body = [
45	    "Task:",
46	    scrub(task, hide),
47	    "",
48	    "=== Change X ===",
49	    scrub(diffX, hide),
50	    "",
51	    "=== Change Y ===",
52	    scrub(diffY, hide),
53	    "",
54	  ].join("\n");
55	  return [
56	    { role: "system", content: SYSTEM },
57	    { role: "user", content: body },
58	  ];
59	}
60	
61	export function parseVerdict(text: string | null): Verdict {
62	  const m = [...(text ?? "").matchAll(/verdict:\s*(X|Y|tie)\b/gi)].at(-1);
63	  if (!m) return "tie";
64	  const v = m[1]!.toUpperCase();
65	  return v === "X" ? "X" : v === "Y" ? "Y" : "tie";
66	}
67	
68	export interface BlindResult {
69	  labels: Record<"X" | "Y", Side>;
70	  verdict: Verdict;
71	  /** The preferred side, or null on a tie. */
72	  preferred: Side | null;
73	  /** The labelled input the judge saw, kept so logs and tests can show it was blind. */
74	  input: ChatMessage[];
75	}
76	
77	/** Labels the two diffs at random, asks the judge, and maps the verdict back to a side. */
78	export async function blindJudge(
79	  llm: LlmClient,
80	  task: string,
81	  diffs: Record<Side, string>,
82	  random: () => number,
83	  hide: string[] = [],
