97	/** Pass beats fail; both pass → the judge's preference; judge tie → a seeded random pick. */
98	export function chooseMerge(pass: Record<Side, boolean>, preferred: Side | null, random: () => number): MergeChoice {
99	  if (pass.old !== pass.new) return { merged: pass.old ? "old" : "new", reason: "pass_beats_fail" };
100	  if (!pass.old) return { merged: null, reason: "both_failed" };
101	  if (preferred) return { merged: preferred, reason: "judge" };
102	  return { merged: random() < 0.5 ? "old" : "new", reason: "random_tie" };
