9	const USAGE = `usage: roster forward --backlog <file> --pair OLD,NEW [--parallel <n>] [--db <path>] [--acceptance <dir>] [--seed <n>]
10	
11	  --backlog <file>    task blocks between "<!-- Txx -->" and "<!-- /Txx -->"
12	  --pair OLD,NEW      the two setup ids (setups/<id>.json); OLD is the incumbent
13	  --parallel <n>      tasks in flight at once (default 4)
14	  --db <path>         state database; finished pairs are skipped on a rerun (default ${DEFAULT_FORWARD_DB})
15	  --acceptance <dir>  pre-committed acceptance tests, one folder per task (default experiments/acceptance)
16	  --seed <n>          run seed for labels and tie-breaks (default random, printed)
17	
18	The blind diff-judge runs on DeepSeek; set DEEPSEEK_API_KEY in .env.`;
19	
20	export interface ForwardArgs {
21	  backlog: string;
22	  old: string;
23	  new: string;
24	  parallel: number;
25	  db: string;
26	  acceptance: string | undefined;
27	  seed: number | undefined;
28	}
29	
30	const FLAGS = ["--backlog", "--pair", "--parallel", "--db", "--acceptance", "--seed"];
31	
32	/** Parses the arguments after `forward`. Throws UsageError on anything it does not accept. */
33	export function parseForwardArgs(args: string[]): ForwardArgs {
34	  const v: Record<string, string> = {};
35	  for (let i = 0; i < args.length; i++) {
36	    const a = args[i]!;
37	    const eq = a.indexOf("=");
38	    const name = eq === -1 ? a : a.slice(0, eq);
39	    if (!FLAGS.includes(name)) throw new UsageError(`unknown argument ${a}`);
40	    const val = eq !== -1 ? a.slice(eq + 1) : args[++i];
41	    if (val === undefined || val.startsWith("--")) throw new UsageError(`${name} needs a value`);
42	    v[name] = val;
43	  }
44	  if (!v["--backlog"]) throw new UsageError("--backlog is required");
45	  const pair = v["--pair"]?.split(",") ?? [];
46	  if (pair.length !== 2 || pair.some((s) => !s)) throw new UsageError("--pair needs OLD,NEW");
47	  const num = (name: string, dflt: number | undefined) => {
48	    if (v[name] === undefined) return dflt;
49	    const n = Number(v[name]);
50	    if (!Number.isInteger(n) || n < 0) throw new UsageError(`${name} must be a non-negative integer, got ${v[name]}`);
51	    return n;
52	  };
53	  const parallel = num("--parallel", 4)!;
54	  if (parallel < 1) throw new UsageError("--parallel must be at least 1");
55	  return {
56	    backlog: v["--backlog"],
57	    old: pair[0]!,
58	    new: pair[1]!,
59	    parallel,
60	    db: v["--db"] ?? DEFAULT_FORWARD_DB,
61	    acceptance: v["--acceptance"],
62	    seed: num("--seed", undefined),
63	  };
64	}
65	
66	export const forwardCommand: Command = {
67	  name: "forward",
68	  summary: "run backlog tasks through two setups, grade blind, merge the winner",
69	  usage: USAGE,
70	  async run(args) {
71	    let a: ForwardArgs;
72	    try {
73	      a = parseForwardArgs(args);
74	    } catch (e) {
75	      if (!(e instanceof UsageError)) throw e;
76	      console.error(`roster forward: ${e.message}\n\n${USAGE}`);
77	      return 2;
78	    }
79	    const res = await runForward({
80	      repo: process.cwd(),
81	      backlog: readFileSync(resolve(a.backlog), "utf8"),
82	      pair: { old: a.old, new: a.new },
83	      parallel: a.parallel,
84	      llm: deepseekClient(),
85	      db: a.db,
86	      acceptanceDir: a.acceptance,
87	      seed: a.seed,
88	      log: (l) => console.log(l),
89	    });
90	    const { stop } = res;
91	    console.log(
92	      `forward: ${res.completed.length} pairs this run, ${res.skipped.length} already done, ${stop.pairs} total; new won ${stop.won}, lost ${stop.lost} discordant`,
93	    );
94	    if (res.reverted) console.log(`forward: stop rule triggered${res.reverted.url ? `, revert PR ${res.reverted.url}` : " (revert PR stubbed)"}`);
95	    return 0;
96	  },
97	};
