52	const unescape = (s: string) =>
53	  s.replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
54	
55	function attr(tag: string, name: string): string | undefined {
56	  const m = new RegExp(`\\s${name}="([^"]*)"`).exec(tag);
57	  return m ? unescape(m[1]!) : undefined;
58	}
