60	/** Per-testcase results from a JUnit file, attributed to the test file of the enclosing suite. */
61	export function parseJunit(xml: string): PerTest[] {
62	  const out: PerTest[] = [];
63	  const stack: string[] = [];
64	  const tokens = xml.match(/<testsuite\b[^>]*>|<\/testsuite>|<testcase\b[^>]*?\/>|<testcase\b[^>]*>[\s\S]*?<\/testcase>/g) ?? [];
65	  for (const t of tokens) {
66	    if (t.startsWith("</testsuite")) stack.pop();
67	    else if (t.startsWith("<testsuite")) stack.push(attr(t, "file") ?? attr(t, "name") ?? stack.at(-1) ?? "");
68	    else {
69	      const head = t.slice(0, t.indexOf(">") + 1);
70	      const file = attr(head, "file") ?? stack.find((s) => /\.[a-z]+$/.test(s)) ?? stack[0] ?? "";
71	      const bad = /<(failure|error)\b/.test(t) || /<skipped\b/.test(t);
72	      out.push({ file, name: attr(head, "name") ?? "", pass: !bad });
73	    }
74	  }
75	  return out;
76	}
