100	    // Capture the agent's change as a patch, then rebuild the tree from base + patch.
101	    runGit(work, ["add", "-A"]);
102	    const patch = runGit(work, ["diff", "--cached", "--binary", sandbox.baseSha]);
103	    const changed = runGit(work, ["diff", "--cached", "--name-only", "-z", sandbox.baseSha]).split("\0").filter(Boolean);
104	    const patchedText = (p: string) => showOrNull(work, ":0", p);
105	    const violations: Violation[] = [
