121	    const suitePass = sh(work, testCmd + junit("suite.xml"), timeout);
122	
123	    for (const h of hidden) {
124	      mkdirSync(dirname(join(work, h.path)), { recursive: true });
125	      writeFileSync(join(work, h.path), h.content);
126	    }
127	    const files = hidden.map((h) => JSON.stringify(h.path)).join(" ");
